// GLN check digit uses the same mod-10 algorithm as GTIN.
bool isValidGln(String gln) {
  if (!RegExp(r'^\d{13}$').hasMatch(gln)) return false;
  final body = gln.substring(0, 12);
  final check = int.parse(gln[12]);
  int sum = 0;
  for (int i = 0; i < body.length; i++) {
    final digit = int.parse(body[body.length - 1 - i]);
    sum += (i.isEven ? 3 : 1) * digit;
  }
  return (10 - sum % 10) % 10 == check;
}

assert(isValidGln('0614141000012'));

